var REGIONAL_KEYWORDS = ["america", "amsterdam", "au", "auckland", "australia", "berlin", "brisbane", "copenhagen", "de", "denmark", "dk", "es", "europe", "fr", "france", "gb", "germany", "it", "italy", "london", "los angeles", "melbourne", "milan", "netherlands", "new york", "new zealand", "nl", "nyc", "nz", "paris", "perth", "scandinavia", "se", "spain", "stockholm", "sweden", "sydney", "uk", "united kingdom", "united states", "us", "usa"];
