function selectKnowledgeModules(question, ctx = {}) {
  const q = " " + (question || "").toLowerCase().replace(/[^a-z0-9']+/g, " ") + " ";
  const scored = [];
  for (const m of DOMAIN_MODULES) {
    let score = 0;
    for (const t of m.triggers) {
      if (t.includes(" ") ? q.includes(t) : q.includes(` ${t} `)) score++;
    }
    if (m.key === "decision") {
      if (ctx.hasPinned) score += 3;
      if (DECISION_FORCERS.some((f) => q.includes(f))) score += 3;
    }
    if (score > 0) scored.push({ key: m.key, text: m.text, score });
  }
  scored.sort((a, b) => b.score - a.score);
  const picked = scored.slice(0, 3).map((s) => s.text);
  const cc = (ctx.countryCode || "").toLowerCase();
  const wantsRegional = REGIONAL_COUNTRY_CODES.has(cc) || REGIONAL_KEYWORDS.some((k) => q.includes(` ${k} `));
  if (wantsRegional && cc !== "in") picked.push(KNOW_REGIONAL);
  return picked.length ? "\n\n" + picked.join("\n\n") : "";
}
var JUDGE_COLOR = `COLOUR \u2014 one temperature per outfit: warm family (camel, tan, cream, chocolate, olive, rust) or cool (black, white, grey, navy, charcoal). Navy, mid-grey, denim and white bridge both. Camel with black is the one licensed cross-family pairing. Tonal and analogous read refined; complementary reads bold and wants one side muted (navy with amber, not cobalt with orange). Proven pairs: navy+camel, olive+rust, charcoal+burgundy, cream+chocolate, emerald+gold, white+light blue+tan, marigold+deep teal. Colour near the face has to flatter a person; colour below the waist only has to agree with the outfit \u2014 so a risky colour in trousers or shoes scores better than the same risk at the collar.`;
